# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::LegacyAuditConversion do
  it "refuses an audit whose associated company differs from its entry's company under the entry's company only" do
    entry_row = { "id" => 5, "company_id" => 1, "created_at" => Time.utc(2026, 1, 2, 3) }
    audit = {
      id: 900, action: "update", associated_type: "Company", associated_id: 2, auditable_id: 5,
      user_type: "User", user_id: 42, username: nil,
      audited_changes: { "note" => ["old", "new"] }, created_at: Time.utc(2026, 2, 3, 4)
    }

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => entry_row })

    # The audit history must not land in another company's audit trail.
    expect(result[:rows]).to be_empty
    expect(result[:refusals].keys).to eq([1])
    expect(result[:refusals].fetch(1).join("\n")).to include("900")
  end
end

require "rails_helper"

RSpec.describe Timekeeping::LegacyAuditConversion do
  it "refuses a username-only audit rather than recording it as the anonymous system actor" do
    entry_row = { "id" => 5, "company_id" => 1, "created_at" => Time.utc(2026, 1, 2, 3) }
    audit = {
      id: 901, action: "update", associated_type: "Company", associated_id: 1, auditable_id: 5,
      user_type: nil, user_id: nil, username: "legacy-importer",
      audited_changes: { "note" => ["old", "new"] }, created_at: Time.utc(2026, 2, 3, 4)
    }

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => entry_row })

    # "Keep its company, author, action, original `created_at` and change values (before and after from `audited_changes`), and set `entry_created_at` from the entry."
    expect(result[:rows]).to be_empty
    message = result[:refusals].fetch(1).join("\n")
    expect(message).to include("901")
    expect(message).to include("legacy-importer")
  end
end

RSpec.describe Timekeeping::LegacyAuditConversion do
  let(:legacy_audit_entry_row) { { "id" => 5, "company_id" => 1, "created_at" => Time.utc(2026, 1, 2, 3) } }

  def legacy_audit(**overrides)
    {
      id: 910, action: "update", associated_type: "Company", associated_id: 1, auditable_id: 5,
      user_type: "User", user_id: 42, username: nil,
      audited_changes: { "note" => ["old", "new"] }, created_at: Time.utc(2026, 2, 3, 4)
    }.merge(overrides)
  end

  it "gives an audit with no user and no username the system actor" do
    audit = legacy_audit(user_type: nil, user_id: nil, username: "")

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:refusals]).to be_empty
    expect(result[:rows].sole).to include("actor_type" => "system", "actor_id" => 0)
  end

  it "converts a destroy audit whose entry is present into the stored values before and an empty object after" do
    audit = legacy_audit(action: "destroy", audited_changes: { "duration" => 60.0, "note" => nil })

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:rows].sole).to include(
      "action" => "destroy", "before" => { "duration" => 60.0, "note" => nil }, "after" => {}
    )
  end

  it "refuses an audit that names no company under its entry's company" do
    audit = legacy_audit(associated_type: nil, associated_id: nil)

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:rows]).to be_empty
    expect(result[:refusals].fetch(1).join("\n")).to include("910", "no company")
  end

  it "refuses an audit whose author type is not User" do
    audit = legacy_audit(user_type: "Agent", user_id: 3)

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:rows]).to be_empty
    expect(result[:refusals].fetch(1).join("\n")).to include("910", "Agent")
  end

  it "builds rows that fit the checkpoint's entry_audits shape" do
    audits = [
      legacy_audit(id: 1, action: "create", audited_changes: { "note" => "first" }),
      legacy_audit(id: 2),
      legacy_audit(id: 3, user_type: nil, user_id: nil)
    ]

    rows = described_class.convert(audits:, entries_by_id: { 5 => legacy_audit_entry_row })[:rows]
    tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }.merge("entry_audits" => rows)

    expect(rows.pluck("id")).to eq([1, 2, 3])
    expect { Timekeeping::Handoff::Checkpoint.check_shape!(tables) }.not_to raise_error
  end
end
